#!/usr/bin/env python3
"""Render measured evidence; never synthesize benchmark samples or overwrite raw results."""
import json,pathlib,statistics,hashlib,re
root=pathlib.Path('.');directory=root/'docs/phase3'
def read(n):return json.loads((directory/n).read_text())
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def fmt(n):return f'{n:.3f}' if isinstance(n,(int,float)) else 'unmeasured'
def median(rows,fn):return statistics.median(fn(r) for r in rows)
w=read('workloads.json');j=read('journal-comparison.json');profile=read('wal-profile-before.json');main=read('mainnet-readonly.json');decode=read('mainnet-readonly.decode.json')
assert w['harnessSha256']==sha('scripts/phase3-benchmark.ts')
assert j['harnessSha256']==sha('scripts/journal-benchmark.ts')
assert w['repetitions']==3 and j['repetitions']==3
for r in w['rows']:
 assert r['completed']==r['offered'] and r['duplicateLogicalProcessing']==0 and r['refused']==0
 assert all(r['integrity'].values())
for r in j['rows']:assert r['completed']==1000
for name,value in w['sourceSha256']['after'].items():assert value==sha('src/'+name+'.ts'),name
old=json.loads(pathlib.Path('docs/phase2/final-source-sha256.json').read_text());original_tests=[p for p in old if p.startswith('tests/')]
assert all(sha(p)==old[p] for p in original_tests)
testlog=(directory/'after-tests.txt').read_text();passed=int(re.search(r'^# pass (\d+)',testlog,re.M)[1]);assert '# fail 0\n' in testlog
phase1before=read('phase1-before.json');phase1after=read('phase1-after.json');phase2before=read('phase2-before.json');phase2after=read('phase2-compatible-after.json')
assert phase1before['workload']['harnessSha256']==phase1after['workload']['harnessSha256']==sha('scripts/benchmark.ts')
assert phase2before['harnessSha256']==phase2after['harnessSha256']==sha('scripts/ingestion-benchmark.ts')
assert phase1before['environment']==phase1after['environment'] and phase2before['environment']==phase2after['environment']
lines=[]
def out(s=''):lines.append(s)
def group(scenario,adapter):return [r for r in w['rows'] if r['scenario']==scenario and r['adapter']==adapter]
out('# Phase 3 engineering report');out();out('Validation completed 2026-11-06. The project was extended in place; dashboard, paper accounting/strategy controls and existing API fields remain. Live mode stays disabled. No application/frontend/container build, deployment, funded transaction, wallet permission or signing path was enabled. Raw artifacts carry their own capture timestamps: the protocol fixture acquisition began on November 3 and final local validation continued on November 6.');out()
a=group('durable-burst-200','after');b=group('durable-burst-200','before');ar=median(a,lambda r:r['completedPerSecond']);br=median(b,lambda r:r['completedPerSecond']);ap=median(a,lambda r:r['latencies']['end_to_end_ms']['p95']);bp=median(b,lambda r:r['latencies']['end_to_end_ms']['p95'])
out('## Outcome');out();out(f'The final comparable durable burst improved from **{fmt(br)} to {fmt(ar)} completed events/s**; median run p95 fell from **{fmt(bp)} to {fmt(ap)} ms**. Both versions completed all 200 offered events per repetition with actual WAL, raw-file and paper Store I/O, and file-fsync ownership before acknowledgement. Group commit adds file/directory syncing in a worker rather than dropping the durability guarantee. These newly measured baselines are distinct from the historical Phase 2 value of 155.779/s; that original result remains unchanged.');out()
a=group('concurrent-history-live','after');b=group('concurrent-history-live','before')
out(f'Under 1,000 historical plus 100 live inputs, fresh-event p95 improved from **{fmt(median(b,lambda r:r["latencies"]["live_end_to_end_ms"]["p95"]))} to {fmt(median(a,lambda r:r["latencies"]["live_end_to_end_ms"]["p95"]))} ms**, while total throughput declined from {fmt(median(b,lambda r:r["completedPerSecond"]))} to {fmt(median(a,lambda r:r["completedPerSecond"]))}/s. That fairness tradeoff is reported, not hidden. Unique-mint throughput is slightly lower in this sample; repeated-mint changes are small and neither is a statistical performance guarantee. All offline completion populations match, all recorded integrity flags pass and no duplicate logical callbacks occurred.');out()
out(f'**{passed} tests pass**, including all original 72 tests with the original test files unchanged. Type checks pass for source, tests, scripts and frontend (`noEmit`). Four real finalized creation transactions validate selected Pump, PumpSwap, Raydium CPMM and Meteora DLMM variants. This is not full platform/version coverage or a verified executable price feed.');out()
out('## Audit and measured bottleneck');out();out('The source audit covered EventJournal, ingestion/stages, backfill, monitoring integration, Store, chain/decoder registry, telemetry and existing fixtures/tests. Phase 2 appended and fsynced each ownership record and completion on the main event loop. Its checkpoint serialization/write/rename also ran there. Each paper Store snapshot still writes and renames separately. The original instrumentation and source archive were captured before these changes; optimization was based on the instrumented I/O profile, not README claims.');out()
out('| Baseline direct WAL profile | Count | Total ms | p50 ms | p95 ms | p99 ms |');out('| --- | ---: | ---: | ---: | ---: | ---: |')
for key in ['fsyncSync','writeSync','JSON.stringify','offer','complete','compact']:
 r=profile['stages'][key];out(f'| {key} | {r["count"]} | {fmt(r["totalMs"])} | {fmt(r["p50"])} | {fmt(r["p95"])} | {fmt(r["p99"])} |')
out();out(f'The 1,000-event direct WAL profile took {fmt(profile["elapsedMs"])} ms and delayed a ready zero-delay timer by {fmt(profile["zeroDelayTimerObservedMs"])} ms. Observed main-thread GC time was {fmt(profile["gc"]["totalMs"])} ms over {profile["gc"]["count"]} delivered GC entries. Instrumentation hooks and nested timings overlap; totals must not be summed. [Raw profile](phase3/wal-profile-before.json) includes CPU, memory and source hash. Compaction was forced once; no general compaction-tail SLO is inferred from one sample.');out()
out('## Isolated WAL comparison');out();out('Same 1,000 offers, 64-offer cohorts, equal completion populations and three seeded randomized adapter-order repetitions. Worker startup and fixture generation are excluded. Both implementations fsync WAL file data before ownership/completion acknowledgement; the worker also syncs its parent directory. The new checksummed envelope is included in worker cost.');out()
out('| Adapter | Completed/s | Receipt→completion p50 ms | p95 ms | p99 ms | Event-loop max ms | Process CPU ms | Data-ack groups |');out('| --- | ---: | ---: | ---: | ---: | ---: | ---: | --- |')
for adapter in ['sync','worker']:
 rs=[r for r in j['rows'] if r['adapter']==adapter];h=lambda r:r['latency']['receipt_to_completion_ms']
 out(f'| {adapter} | {fmt(median(rs,lambda r:r["completedPerSecond"]))} | {fmt(median(rs,lambda r:h(r)["p50"]))} | {fmt(median(rs,lambda r:h(r)["p95"]))} | {fmt(median(rs,lambda r:h(r)["p99"]))} | {fmt(median(rs,lambda r:r["eventLoopDelayMs"]["max"]))} | {fmt(median(rs,lambda r:(r["cpuMicroseconds"]["user"]+r["cpuMicroseconds"]["system"])/1000))} | {"per-record sync; not batch-counted" if adapter=="sync" else str(int(median(rs,lambda r:r["telemetry"]["counters"]["journal.fsync_batches"])))} |')
out();out('Group counts are acknowledged record groups, not individual fsync system-call counts. File/directory sync and checkpoint syncs are distinct operations. [Per-run JSON](phase3/journal-comparison.json) records distributions, memory, CPU, writer counters and ordering seed. Cold worker startup costs remain real even though excluded from this warm throughput comparison.');out()
out('## Full pipeline workloads: equal completion populations');out();out(f'Environment: {w["environment"]["node"]}, {w["environment"]["cpu"]}. The identical source harness runs three randomized repetitions using seed {w["seed"]}. Each cell below is the median of run-level values, not a pooled quantile. Ten-thousand-event unique-mint fixtures contain 10,000 distinct encoded mint/PDA pairs; repeated-mint fixtures contain one mint. Independent synthetic paper quotes retain the original safety and five-position cap. Most completions are strategy evaluations/rejections, not buys.');out()
out('| Workload | Version | Completed/run | p50 ms | p95 ms | p99 ms | Completed/s | Fresh live p95 ms |');out('| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |')
for scenario in ['unique-mints-10000','repeated-mint-10000','durable-burst-200','sustained-stream','concurrent-history-live','slow-unavailable-rpc']:
 for adapter in ['before','after']:
  rs=group(scenario,adapter);h=lambda r:r['latencies']['end_to_end_ms']
  out(f'| {scenario} | {adapter} | {rs[0]["completed"]} | {fmt(median(rs,lambda r:h(r)["p50"]))} | {fmt(median(rs,lambda r:h(r)["p95"]))} | {fmt(median(rs,lambda r:h(r)["p99"]))} | {fmt(median(rs,lambda r:r["completedPerSecond"]))} | {fmt(median(rs,lambda r:r["latencies"]["live_end_to_end_ms"]["p95"]))} |')
out();out('Only durable-burst writes real WAL, direct raw append and paper Store snapshots. The comparison preserves the same raw append callback; it does not benchmark production raw rotation or a high-water compaction workload. Other pipeline workloads use in-memory ownership and exercise scheduler/decoder/Store overhead. Sustained delivery paces 64 offers/20 ms for a finite 1,000-event fixture; it is not a multi-hour soak or an open-loop production traffic generator. Slow/unavailable RPC is injected: each 37th identity fails its first two attempts before succeeding. That workload is not live provider risk evidence. No completion/refusal population was trimmed to obtain an improvement.');out()
out('Measured regressions/tradeoffs:');out()
for scenario in ['unique-mints-10000','repeated-mint-10000','durable-burst-200','sustained-stream','concurrent-history-live','slow-unavailable-rpc']:
 b=group(scenario,'before');a=group(scenario,'after');rb=median(b,lambda r:r['completedPerSecond']);ra=median(a,lambda r:r['completedPerSecond']);pb=median(b,lambda r:r['latencies']['end_to_end_ms']['p95']);pa=median(a,lambda r:r['latencies']['end_to_end_ms']['p95'])
 out(f'- {scenario}: throughput {(ra/rb-1)*100:+.2f}%; overall p95 {(pa/pb-1)*100:+.2f}%.')
out();out('The pinned low-level Pump decoder and its cache were not changed in Phase 3. New full-transaction verification is an additional capability with additional work, not a claim that its latency equals log-only decode. Small percent changes have no confidence interval or proven significance. Fair scheduling intentionally shifts waiting time from fresh events toward older backlog; total throughput can decline. Group collection can add low-load acknowledgement delay.');out()
out('| Workload | Version | Peak sampled RSS MiB | Peak sampled heap MiB | Process CPU ms | Event-loop p95 ms | Event-loop max ms | Observed main GC ms | Peak journal pending | RPC faults |');out('| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |')
for scenario in ['unique-mints-10000','repeated-mint-10000','durable-burst-200','sustained-stream','concurrent-history-live','slow-unavailable-rpc']:
 for adapter in ['before','after']:
  rs=group(scenario,adapter);out(f'| {scenario} | {adapter} | {fmt(median(rs,lambda r:r["sampledPeakRssBytes"]/1048576))} | {fmt(median(rs,lambda r:r["sampledPeakHeapBytes"]/1048576))} | {fmt(median(rs,lambda r:(r["cpuMicroseconds"]["user"]+r["cpuMicroseconds"]["system"])/1000))} | {fmt(median(rs,lambda r:r["eventLoopDelayMs"]["p95"]))} | {fmt(median(rs,lambda r:r["eventLoopDelayMs"]["max"]))} | {fmt(median(rs,lambda r:r["gc"]["totalMs"]))} | {fmt(median(rs,lambda r:r["journal"].get("pendingPeak"))) if adapter=="after" else "unmeasured"} | {int(median(rs,lambda r:r["rpcErrors"]))} |')
out();out('RSS/heap are sampled (5 ms plus offer cohorts) and include already-generated fixtures and process history; a sample can miss a brief peak. CPU is process accounting, GC observations cover delivered main-thread entries, and worker GC is not separately profiled. Memory bounds come from queue/byte limits and tests, not from treating sampled RSS as a ceiling. Raw JSON includes every stage queue-wait distribution, occupancy peak, WAL byte count, ownership/completion acknowledgements and retry/error count. Journal `pendingPeak` is newly measured; no baseline peak is invented.');out()
soak=read('soak.json')
assert soak['offered']==soak['completed'] and soak['refused']==0 and soak['duplicateCallbacks']==0
out('## Bounded wall-time durability soak');out();out(f"A separate after-only observation experiment ran for {fmt(soak['offerWindowMs']/1000)} s at a target {soak['targetEventsPerSecond']}/s: {soak['offered']} offered and {soak['completed']} completed, with zero refusals/duplicate callbacks. Receipt-to-completion p95 was {fmt(soak['latencies']['receipt_to_completion_ms']['p95'])} ms; event-loop p95 {fmt(soak['eventLoopDelayMs']['p95'])} ms. End pending/quarantine was {soak['journal']['pending']}/{soak['journal']['quarantined']}. The durable WAL was real; logs were empty observation-only fixtures, with no Store/raw writes, paper quotes or RPC. Measurement maps and total inputs are capped at 10,000. This short finite health observation is not a comparative speedup or production endurance proof. [Soak JSON](phase3/soak.json).");out()
out('## Recorded finalized launch replay');out();out('| Run | Decode attempts | Distinct captures | Verified results | Local decode p50 ms | p95 ms | p99 ms | Total ms |');out('| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |')
for r in w['realReplay']:
 h=r['latencies']['recorded_verified_decode_ms'];out(f'| {r["repetition"]} | {r["decodeAttempts"]} | {r["distinctFinalizedTransactions"]} | {r["verifiedResults"]} | {fmt(h["p50"])} | {fmt(h["p95"])} | {fmt(h["p99"])} | {fmt(r["elapsedMs"])} |')
out();out('Each run repeats four real captures 100 times. It does not contain 400 distinct launches. Their pinned instruction/event schemas, invocation boundaries, successful status and later finalized account evidence are validated. Accounts are not reconstructed at the creation slot; mutable present-day state is not used to invent original liquidity or prices. [Coverage/provenance matrix](phase3/protocol-coverage.md) lists exact enabled variants, program IDs, commits, signatures and version limits. Future/other layouts remain disabled.');out()
out('## Retained Phase 1 and Phase 2 compatibility runs');out();out('The original harness files remain byte-identical. The following Phase 1 before/after runs use 1,000 primary offers and three repetitions on the same host; overload includes its existing reconnect re-offer. These exercise the compatibility path, not worker-backed runtime admission.');out()
out('| Phase 1 scenario | Version | p95 ms | Completed/s | Completed / duplicate / refused |');out('| --- | --- | ---: | ---: | --- |')
for scenario in ['sequential','dedupe-burst','overload-reconnect']:
 for label,data in [('before',phase1before),('after',phase1after)]:
  rs=[r for r in data['results'] if r['scenario']==scenario];r=rs[0];out(f'| {scenario} | {label} | {fmt(median(rs,lambda r:r["latencies"]["replay.end_to_end_ms"]["p95"]))} | {fmt(median(rs,lambda r:r["completedEventsPerSecond"]))} | {r["completed"]} / {r["duplicates"]} / {r["dropped"]} |')
out();out('| Original Phase 2 workload | Version | Completed / unique | p95 ms | Completed/s | Refused / recovered / uncompleted |');out('| --- | --- | --- | ---: | ---: | --- |')
for i in range(len(phase2before['results'])):
 for label,data in [('before',phase2before),('compatible after',phase2after)]:
  r=data['results'][i];out(f'| {r["scenario"]} | {label} | {r["completed"]} / {r["uniqueOffered"]} | {fmt(r["latencies"]["end_to_end_ms"]["p95"])} | {fmt(r["completedEventsPerSecond"])} | {r["knownRefusedAdmissions"]} / {r["recovered"]} / {r["uncompletedFixtureEvents"]} |')
out();out('These Phase 2 runs explicitly construct the synchronous journal; they preserve the original harness and do not select the new worker runtime. Their single-run values and changed success populations (where applicable) are not substituted for the equal-population three-run worker comparison. Any slower compatibility result remains visible in this table. [Before](phase3/phase2-before.json) and [compatible after](phase3/phase2-compatible-after.json) retain full telemetry.');out()
out('## Optional mainnet read-only experiment');out();out(f'The bounded public-provider collector recorded **{main["metrics"].get("observations",0)} actual confirmed observations**, {main["metrics"].get("duplicates",0)} duplicate receipts, {main["metrics"].get("rpc_errors",0)} RPC errors and {main["metrics"].get("provider_429",0)} HTTP 429s during this final sample. Capture duration was {fmt(main.get("captureElapsedSeconds"))} s (including initial head/subscription/reconnect work), with {fmt(main.get("observationsPerSecond"))} captured observations/s. The configured observation cap was {main["observationLimit"]}; reaching it limits coverage. Earlier fixture acquisition did encounter rate-limit/unsupported-version failures, retained in acquisition logs; a zero in this short final run does not erase them.');out()
out('| Read-only measurement | Samples | p50 ms | p95 ms | p99 ms |');out('| --- | ---: | ---: | ---: | ---: |')
for name,r in main['latencies'].items():out(f'| {name} | {r["count"]} | {fmt(r["p50"])} | {fmt(r["p95"])} | {fmt(r["p99"])} |')
out();out(f'Local replay examined {decode["pumpObservations"]} Pump observations and decoded **{decode["distinctDecodedMints"]} distinct Pump launch mints**, with {decode["decodeFailures"]} decoder failures. No observed launch throughput is claimed when no CreateEvent was present. The separate recorded fixtures supply real positive launch cases. Token-balance mint distribution, if present, describes only the bounded transaction retrieval sample, not every observation or a launch assertion.');out()
out(f'Signed slot-lag summary: `{json.dumps(main["slotLagSigned"],sort_keys=True)}`. The head is a pre-window snapshot; negative lag means that snapshot is stale relative to later receipts. It is not negative network latency and is not converted into milliseconds. Historical checks scan at most 100 signatures/program and explicitly label sampled missing receipts/page caps as partial coverage. No exhaustive mainnet recovery, precise chain-event-to-receipt latency or permanent-loss count is claimed. The collector is independent of the Node WAL pipeline; its network results cannot substantiate mainnet funded or durable-processing throughput. [Network JSON](phase3/mainnet-readonly.json), [bounded observations](phase3/mainnet-readonly.observations.json), [decode JSON](phase3/mainnet-readonly.decode.json).');out()
out('## Correctness and durability validation');out();out(f'The final log reports **{passed} passed / 0 failed**. Hashes verify all {len(original_tests)} original test/helper files recorded at Phase 2 are unchanged. Tests add grouped fsync ownership, duplicate in-flight offers/responses, bounded writer pressure, ENOSPC at write/sync, checksummed corruption, truncated tail, explicit worker failure, restart replay, SIGKILL between ownership/paper commit and completion, weighted live/history fairness, stale/unknown freshness rejection, four real protocol positive fixtures plus malformed negatives, archive retention/tombstones and fork/provider conflicts. No original readiness timeout or assertion was weakened. An earlier run overlapped a smoke benchmark and hit the existing API cold-start deadline; it was discarded, then the final suite and performance runs were executed separately.');out()
out('Checks establish the tested supported crash window, not unlimited exactly-once execution. Work is not processed before durable ownership. Completion acknowledgement follows its fsynced completion record. A crash may still replay an acknowledged-owned event whose completion was not acknowledged. Callbacks must be idempotent; the paper seen-ID horizon is finite. ENOSPC is deterministic failure injection, not an actual disk-filling experiment. Physical power cuts and arbitrary filesystem/device failure were not tested.');out()
out('## Remaining risks and next phase');out();out('1. The paper Store and WAL/raw/SQL are not one atomic ledger. Store snapshots still lack file fsync; retained paper IDs do not guarantee exactly-once purchases forever. Funded execution needs a separate transactional execution ledger, reconciliation and signer review.');out('2. Worker startup, IPC/copying, checksums and group collection add costs. Fresh fairness improves fresh latency while reducing mixed-load total throughput; cold unique-mint gains are not demonstrated. Evaluate these tradeoffs under longer representative load before setting an SLO.');out('3. Coverage is four pinned creation variants and four real positive captures, not every program upgrade or launch route. Deployment slots/IDL versions do not prove historical binary identity. Later account snapshots cannot prove initial liquidity, prices, sellability or token risk. Expand independently verified fixtures before enabling another variant.');out('4. Provider history/finality is bounded and fallible. Slot/log conflicts fail closed with gaps; no automatic accounting rollback, cryptographic completeness proof or independent-provider finalized-history reconciliation exists. Finality delays/RPC failures can quarantine accepted work.');out('5. Raw retention deliberately removes old audit payloads after preserving bounded cumulative coverage metadata. It is not permanent complete history. Legacy oversized archives and external disk growth require operator monitoring; free-disk/WAL metrics are sampled at writer activity, not an independent continuous disk monitor.');out('6. The public run is short and cap-limited, and the sustained fixture is finite. No multi-hour soak, production memory ceiling, broad RPC-provider comparison, funded benchmark or profitability claim is supported.');out('7. The end-to-end Node verification service was not proven against the public provider in this environment: a direct Node RPC probe timed out, while the independent Python collector succeeded. Local HTTP/WebSocket integration and replay of captured finalized evidence passed. Provider transport compatibility needs a deployment-specific check.');out('8. Next priorities: longer constrained-traffic soak and slow-storage stress; archived program binaries/additional layout fixtures; explicit finality/fork reconciliation; durable verification-issue audit across restart; and independently reviewed transactional paper/account persistence before any funded design. Live mode remains rejected.');out()
out('## Reproduction and evidence');out();out('[Commands, architecture and operations](phase3/README.md) · [WAL durability contract](phase3/wal-durability.md) · [protocol matrix](phase3/protocol-coverage.md) · [baseline source archive](phase3/before-source.tar.gz) · [final test log](phase3/after-tests.txt) · [type checks](phase3/typecheck.txt) · [full workloads](phase3/workloads.json) · [WAL comparison](phase3/journal-comparison.json). Source/schema/fixture/harness manifests identify the measured inputs. The generator verifies harness/source compatibility, equal populations, test preservation and integrity flags; it does not manufacture samples or infer unavailable results.')
(root/'docs/phase3-engineering-report.md').write_text('\n'.join(lines)+'\n')
